<template><ForgeDialog title="RSA key generator" description="Generate a local public/private RSA key pair." eyebrow="WORKSPACE / SECURITY" wide @close="emit('close')"><div class="rsa-panel"><div class="rsa-toolbar"><label>Key size <input v-model.number="bits" type="number" min="512" max="16384" step="8" /></label><button class="primary-button" :disabled="loading" @click="generate">{{ loading ? 'Generating…' : 'Generate key pair' }}</button></div><p v-if="error" class="forge-alert forge-alert--error">{{ error }}</p><div class="rsa-columns"><section><div><b>Public key</b><button class="text-button" @click="copy(publicKey)">Copy</button></div><textarea :value="publicKey" readonly rows="14" /></section><section><div><b>Private key</b><button class="text-button" @click="copy(privateKey)">Copy</button></div><textarea :value="privateKey" readonly rows="14" /></section></div></div></ForgeDialog></template>
<script setup lang="ts">
import { ref } from 'vue'
import ForgeDialog from './ForgeDialog.vue'
import { clipboard, nodeForge } from '@/util/NodeFn'
const emit=defineEmits<{close:[]}>(); const bits=ref(2048); const publicKey=ref(''); const privateKey=ref(''); const loading=ref(false); const error=ref(''); const generate=async()=>{if(bits.value<512||bits.value>16384||bits.value%8){error.value='Key size must be 512–16384 bits and a multiple of 8.';return}loading.value=true;error.value='';publicKey.value='';privateKey.value='';try{const pair=await nodeForge.rsaGenerateKeyPair({bits:bits.value});publicKey.value=pair.publicKey;privateKey.value=pair.privateKey}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{loading.value=false}};const copy=(value:string)=>clipboard.writeText(value); void generate()
</script>
<style scoped>.rsa-panel{display:grid;gap:14px}.rsa-toolbar{display:flex;align-items:end;gap:10px}.rsa-toolbar label{display:grid;gap:7px;color:var(--pqt-text-muted);font-size:11px}.rsa-toolbar input{width:130px;padding:9px;color:var(--pqt-text);background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:12px var(--pqt-font-mono)}.rsa-columns{display:grid;grid-template-columns:1fr 1fr;gap:12px}.rsa-columns section{display:grid;gap:7px}.rsa-columns section>div{display:flex;justify-content:space-between;align-items:center}.rsa-columns textarea{width:100%;resize:vertical;padding:10px;color:#b3d7ce;background:var(--pqt-canvas);border:1px solid var(--pqt-border-strong);border-radius:7px;font:10px/1.5 var(--pqt-font-mono)}</style>
